// Hand-written. Not generated by Speakeasy.
//
// Reordering a list that is already in state used to plan a change for ever.
//
// Writing a list out of order on create settles, because the KeepOrder plan
// modifiers hold the stored order. Changing only the order of a list already
// in state does not, and the reason is where the framework does its work:
//
//	server_planresourcechange.go:252  computed nulls become unknown
//	server_planresourcechange.go:293  attribute plan modifiers run
//	server_planresourcechange.go:313  the resource's ModifyPlan runs
//
// The proposed new state differs from prior state as soon as the list is
// reordered, so step 252 marks every computed-and-null attribute unknown.
// Step 293 then restores the list, but the unknowns it caused are already
// there and nothing takes them back. The plan reads "1 to change" with about
// 174 attributes as "known after apply", the apply sends nothing the server
// treats as a change, state keeps the old order, and the next plan says the
// same thing again.
//
// Every import hits this, because imported state holds Authlete's order, so
// any configuration written in a different order never converges.
//
// By the time step 313 runs, the ordering modifiers have already put the
// lists back. So if the plan still differs from prior state, and every
// difference is an unknown this process created, then nothing real is
// changing and prior state is the correct plan.
//
// Anything else stops it: a value that is known and different is a genuine
// change, and the plan is left alone.
package provider

import (
	"context"

	"github.com/authlete/terraform-provider-authlete/v3/internal/provider/customtypes"
	"github.com/hashicorp/terraform-plugin-framework/resource"
	"github.com/hashicorp/terraform-plugin-go/tftypes"
)

var (
	_ resource.ResourceWithModifyPlan = (*ServiceResource)(nil)
	_ resource.ResourceWithModifyPlan = (*ClientResource)(nil)
)

// ModifyPlan is declared here rather than in the generated resource, which
// has none. The framework finds it through ResourceWithModifyPlan, so no
// generated file needs patching.
func (r *ServiceResource) ModifyPlan(ctx context.Context, req resource.ModifyPlanRequest, resp *resource.ModifyPlanResponse) {
	keepPriorWhenNothingChanged(req, resp)
}

func (r *ClientResource) ModifyPlan(ctx context.Context, req resource.ModifyPlanRequest, resp *resource.ModifyPlanResponse) {
	keepPriorWhenNothingChanged(req, resp)
}

// keepPriorWhenNothingChanged replaces the plan with prior state when the two
// differ only by unknowns.
//
// Terraform core accepts a planned state equal to prior state as long as both
// prior state and configuration are non-null, which is exactly the update
// case this covers. Create and destroy are left alone: there is no prior
// state to keep on one, and nothing to plan on the other.
func keepPriorWhenNothingChanged(req resource.ModifyPlanRequest, resp *resource.ModifyPlanResponse) {
	if req.State.Raw.IsNull() || req.Plan.Raw.IsNull() {
		return
	}
	if resp.Plan.Raw.IsNull() {
		return
	}
	// An unknown is only noise when the framework invented it. One that comes
	// from the configuration is a value the user asked for and the provider
	// cannot see yet, such as jwks built from a tls_private_key being created
	// in the same run, which is the key rotation the migration guide
	// recommends. Absorbing that showed "No changes" for a real edit and
	// silently skipped the rotation.
	//
	// Telling the two apart per attribute is possible but easy to get wrong,
	// and getting it wrong loses a change silently. So the whole optimisation
	// stands down whenever the configuration holds an unknown anywhere. The
	// cost is that a reorder in a configuration that also depends on a
	// resource being created will not settle until the next run, which is the
	// behaviour before this fix and is visible rather than silent.
	if containsUnknown(req.Config.Raw) {
		return
	}
	if onlyUnknownsDiffer(resp.Plan.Raw, req.State.Raw) {
		resp.Plan.Raw = req.State.Raw
	}
}

// containsUnknown reports whether any value anywhere beneath v is unknown.
func containsUnknown(v tftypes.Value) bool {
	found := false
	// Walk visits v and every value beneath it. The error return is for the
	// callback; this one never fails.
	_ = tftypes.Walk(v, func(_ *tftypes.AttributePath, val tftypes.Value) (bool, error) {
		if found {
			return false, nil
		}
		if !val.IsKnown() {
			found = true
			return false, nil
		}
		return true, nil
	})
	return found
}

// onlyUnknownsDiffer reports whether every place the plan differs from prior
// state is an unknown in the plan.
//
// An unknown is the framework saying "the API will decide this", which is
// only true if something real is being sent. Where nothing real is being
// sent, prior state is the better answer.
func onlyUnknownsDiffer(plan, state tftypes.Value) bool {
	// The framework put this here because it thought the resource was
	// changing. That is the thing being disproved, so it is not a difference.
	if !plan.IsKnown() {
		return true
	}
	if plan.IsNull() != state.IsNull() {
		return false
	}
	if plan.IsNull() {
		return true
	}
	// Prior state should never hold an unknown. If it somehow does, there is
	// nothing to compare against and the plan stands.
	if !state.IsKnown() {
		return false
	}

	switch plan.Type().(type) {
	case tftypes.Object, tftypes.Map:
		var p, s map[string]tftypes.Value
		if plan.As(&p) != nil || state.As(&s) != nil {
			return false
		}
		if len(p) != len(s) {
			return false
		}
		for name, pv := range p {
			sv, ok := s[name]
			if !ok {
				return false
			}
			// Import has no configured spelling of a JWK Set to preserve, so
			// state initially contains Authlete's JSON formatting. Semantic
			// equality on the custom type handles refresh, but does not make
			// raw planned strings equal during planning. Use the same JSON
			// comparison here before deciding that the import changed a key.
			if (name == "jwks" || name == "federation_jwks" || name == "credential_jwks") && equivalentKeySets(pv, sv) {
				continue
			}
			if !onlyUnknownsDiffer(pv, sv) {
				return false
			}
		}
		return true

	case tftypes.List, tftypes.Set, tftypes.Tuple:
		var p, s []tftypes.Value
		if plan.As(&p) != nil || state.As(&s) != nil {
			return false
		}
		if len(p) != len(s) {
			return false
		}
		// Compared by position on purpose. The ordering modifiers have
		// already run, so a list that Authlete reorders matches here; one
		// that genuinely moved does not, and that is a real change.
		for i := range p {
			if !onlyUnknownsDiffer(p[i], s[i]) {
				return false
			}
		}
		return true

	default:
		return plan.Equal(state)
	}
}

func equivalentKeySets(plan, state tftypes.Value) bool {
	if !plan.IsKnown() || !state.IsKnown() || plan.IsNull() || state.IsNull() {
		return false
	}
	var planned, stored string
	if plan.As(&planned) != nil || state.As(&stored) != nil {
		return false
	}
	same, diags := customtypes.NewJWKSValue(stored).StringSemanticEquals(
		context.Background(), customtypes.NewJWKSValue(planned),
	)
	return !diags.HasError() && same
}
